PRAGMA foreign_keys = OFF;
BEGIN TRANSACTION;
CREATE TABLE alembic_version (
	version_num VARCHAR(32) NOT NULL, 
	CONSTRAINT alembic_version_pkc PRIMARY KEY (version_num)
);
CREATE TABLE author (
	name VARCHAR(75) NOT NULL, 
	id INTEGER NOT NULL, 
	CONSTRAINT pk_author PRIMARY KEY (id), 
	CONSTRAINT uq_author_name UNIQUE (name)
);
CREATE TABLE cdli_artifact (
	tablet_id INTEGER NOT NULL, 
	p_number VARCHAR(12) NOT NULL, 
	designation VARCHAR(500) NOT NULL, 
	museum_no VARCHAR(500), 
	accession_no VARCHAR(500), 
	primary_publication VARCHAR(500), 
	publication_history VARCHAR(2000), 
	id INTEGER NOT NULL, period VARCHAR(200), provenience VARCHAR(200), object_type VARCHAR(200), material VARCHAR(200), language VARCHAR(200), 
	CONSTRAINT pk_cdli_artifact PRIMARY KEY (id), 
	CONSTRAINT fk_cdli_artifact_tablet_id_tablet FOREIGN KEY(tablet_id) REFERENCES tablet (id) ON DELETE CASCADE, 
	CONSTRAINT uq_cdli_artifact_tablet_id UNIQUE (tablet_id, p_number)
);
CREATE TABLE "cdp" (
	sign_id INTEGER NOT NULL, 
	form_name VARCHAR(5), 
	variant_name VARCHAR(5), 
	form_description VARCHAR(50), 
	notes VARCHAR(50), 
	id INTEGER NOT NULL, 
	CONSTRAINT pk_cdp PRIMARY KEY (id), 
	CONSTRAINT fk_cdp_sign_id_sign FOREIGN KEY(sign_id) REFERENCES sign (id) ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE TABLE change (
	change_set_id INTEGER NOT NULL, 
	kind VARCHAR(10) NOT NULL, 
	table_name VARCHAR(50) NOT NULL, 
	record_id INTEGER NOT NULL, 
	field VARCHAR(50) NOT NULL, 
	old_value JSON NOT NULL, 
	new_value JSON NOT NULL, 
	id INTEGER NOT NULL, 
	CONSTRAINT pk_change PRIMARY KEY (id), 
	CONSTRAINT ck_change_kind CHECK (kind IN ('insert', 'update')), 
	CONSTRAINT fk_change_change_set_id_change_set FOREIGN KEY(change_set_id) REFERENCES change_set (id)
);
CREATE TABLE change_set (
	author VARCHAR(100) NOT NULL, 
	created_at DATETIME NOT NULL, 
	comment VARCHAR(500), 
	reverts_id INTEGER, 
	id INTEGER NOT NULL, 
	CONSTRAINT pk_change_set PRIMARY KEY (id), 
	CONSTRAINT fk_change_set_reverts_id_change_set FOREIGN KEY(reverts_id) REFERENCES change_set (id)
);
CREATE TABLE city (
	name VARCHAR(100) NOT NULL, 
	locality_id INTEGER, 
	id INTEGER NOT NULL, 
	CONSTRAINT pk_city PRIMARY KEY (id), 
	CONSTRAINT fk_city_locality_id_locality FOREIGN KEY(locality_id) REFERENCES locality (id), 
	CONSTRAINT uq_city_name UNIQUE (name)
);
CREATE TABLE city_site (
	name VARCHAR(100) NOT NULL, 
	city_id INTEGER NOT NULL, 
	id INTEGER NOT NULL, 
	CONSTRAINT pk_city_site PRIMARY KEY (id), 
	CONSTRAINT fk_city_site_city_id_city FOREIGN KEY(city_id) REFERENCES city (id), 
	CONSTRAINT uq_city_site_name UNIQUE (name)
);
CREATE TABLE "correspondent" (
	ruler_id INTEGER, 
	non_ruler_id INTEGER, 
	id INTEGER NOT NULL, 
	CONSTRAINT pk_correspondent PRIMARY KEY (id), 
	CONSTRAINT fk_correspondent_ruler_id_ruler FOREIGN KEY(ruler_id) REFERENCES ruler (id), 
	CONSTRAINT fk_correspondent_non_ruler_id_non_ruler_corresp FOREIGN KEY(non_ruler_id) REFERENCES non_ruler_corresp (id), 
	CONSTRAINT ck_correspondent_one_party CHECK ((ruler_id IS NULL) != (non_ruler_id IS NULL))
);
CREATE TABLE dynasty (
	name VARCHAR(100) NOT NULL, 
	id INTEGER NOT NULL, 
	CONSTRAINT pk_dynasty PRIMARY KEY (id), 
	CONSTRAINT uq_dynasty_name UNIQUE (name)
);
CREATE TABLE eponym (
	name VARCHAR(50) NOT NULL, 
	id INTEGER NOT NULL, 
	CONSTRAINT pk_eponym PRIMARY KEY (id), 
	CONSTRAINT uq_eponym_name UNIQUE (name)
);
CREATE TABLE eponym_year (
	year INTEGER NOT NULL, 
	eponym_id INTEGER NOT NULL, 
	CONSTRAINT pk_eponym_year PRIMARY KEY (year), 
	CONSTRAINT fk_eponym_year_eponym_id_eponym FOREIGN KEY(eponym_id) REFERENCES eponym (id)
);
CREATE TABLE function (
	name VARCHAR(50) NOT NULL, 
	id INTEGER NOT NULL, 
	CONSTRAINT pk_function PRIMARY KEY (id), 
	CONSTRAINT uq_function_name UNIQUE (name)
);
CREATE TABLE genre (
	name VARCHAR(100) NOT NULL, 
	id INTEGER NOT NULL, 
	CONSTRAINT pk_genre PRIMARY KEY (id), 
	CONSTRAINT uq_genre_name UNIQUE (name)
);
CREATE TABLE "instance" (
	tablet_id INTEGER NOT NULL, 
	sign_id INTEGER NOT NULL, 
	surface_id INTEGER, 
	function_id INTEGER, 
	notes VARCHAR(250), 
	jjt_notes VARCHAR(250), 
	filename VARCHAR(50) NOT NULL, 
	id INTEGER NOT NULL, 
	language_id INTEGER, 
	column_number VARCHAR(10), 
	line_number VARCHAR(10), 
	iteration_number VARCHAR(10), 
	CONSTRAINT pk_instance PRIMARY KEY (id), 
	CONSTRAINT fk_instance_sign_id_sign FOREIGN KEY(sign_id) REFERENCES sign (id) ON DELETE CASCADE ON UPDATE CASCADE, 
	CONSTRAINT fk_instance_surface_id_surface FOREIGN KEY(surface_id) REFERENCES surface (id), 
	CONSTRAINT uq_instance_filename UNIQUE (filename), 
	CONSTRAINT fk_instance_function_id_function FOREIGN KEY(function_id) REFERENCES function (id), 
	CONSTRAINT fk_instance_tablet_id_tablet FOREIGN KEY(tablet_id) REFERENCES tablet (id) ON DELETE CASCADE ON UPDATE CASCADE, 
	CONSTRAINT fk_instance_language_id_language FOREIGN KEY(language_id) REFERENCES language (id)
);
CREATE TABLE language (
	name VARCHAR(100) NOT NULL, 
	id INTEGER NOT NULL, 
	CONSTRAINT pk_language PRIMARY KEY (id), 
	CONSTRAINT uq_language_name UNIQUE (name)
);
CREATE TABLE locality (
	area VARCHAR(100) NOT NULL, 
	id INTEGER NOT NULL, 
	CONSTRAINT pk_locality PRIMARY KEY (id), 
	CONSTRAINT uq_locality_area UNIQUE (area)
);
CREATE TABLE medium (
	name VARCHAR(50) NOT NULL, 
	id INTEGER NOT NULL, 
	CONSTRAINT pk_medium PRIMARY KEY (id), 
	CONSTRAINT uq_medium_name UNIQUE (name)
);
CREATE TABLE method (
	name VARCHAR(50) NOT NULL, 
	id INTEGER NOT NULL, 
	CONSTRAINT pk_method PRIMARY KEY (id), 
	CONSTRAINT uq_method_name UNIQUE (name)
);
CREATE TABLE non_ruler_corresp (
	name VARCHAR(100) NOT NULL, 
	id INTEGER NOT NULL, 
	CONSTRAINT pk_non_ruler_corresp PRIMARY KEY (id), 
	CONSTRAINT uq_non_ruler_corresp_name UNIQUE (name)
);
CREATE TABLE oracc_list_number (
	oracc_sign_id INTEGER NOT NULL, 
	list_name VARCHAR(20) NOT NULL, 
	number VARCHAR(50) NOT NULL, 
	id INTEGER NOT NULL, 
	CONSTRAINT pk_oracc_list_number PRIMARY KEY (id), 
	CONSTRAINT fk_oracc_list_number_oracc_sign_id_oracc_sign FOREIGN KEY(oracc_sign_id) REFERENCES oracc_sign (id) ON DELETE CASCADE, 
	CONSTRAINT uq_oracc_list_number_oracc_sign_id UNIQUE (oracc_sign_id, list_name, number)
);
CREATE TABLE oracc_sign (
	oid VARCHAR(12) NOT NULL, 
	name VARCHAR(200) NOT NULL, 
	ebl_url VARCHAR(500), 
	id INTEGER NOT NULL, cuneiform VARCHAR(30), 
	CONSTRAINT pk_oracc_sign PRIMARY KEY (id), 
	CONSTRAINT uq_oracc_sign_oid UNIQUE (oid)
);
CREATE TABLE oracc_text (
	tablet_id INTEGER NOT NULL, 
	project VARCHAR(50) NOT NULL, 
	text_id VARCHAR(12) NOT NULL, 
	id INTEGER NOT NULL, 
	CONSTRAINT pk_oracc_text PRIMARY KEY (id), 
	CONSTRAINT fk_oracc_text_tablet_id_tablet FOREIGN KEY(tablet_id) REFERENCES tablet (id) ON DELETE CASCADE, 
	CONSTRAINT uq_oracc_text_tablet_id UNIQUE (tablet_id, project, text_id)
);
CREATE TABLE "period" (
	name VARCHAR(150) NOT NULL, 
	id INTEGER NOT NULL, 
	start_year INTEGER, 
	end_year INTEGER, 
	CONSTRAINT pk_period PRIMARY KEY (id), 
	CONSTRAINT uq_period_name UNIQUE (name)
);
CREATE TABLE "reign" (
	ruler_id INTEGER NOT NULL, 
	rim_ref VARCHAR(50) NOT NULL, 
	city_id INTEGER, 
	dynasty_id INTEGER, 
	period_id INTEGER NOT NULL, 
	sub_period_id INTEGER, 
	id INTEGER NOT NULL, 
	start_year INTEGER, 
	end_year INTEGER, 
	CONSTRAINT pk_reign PRIMARY KEY (id), 
	CONSTRAINT fk_reign_sub_period_id_sub_period FOREIGN KEY(sub_period_id) REFERENCES sub_period (id), 
	CONSTRAINT fk_reign_ruler_id_ruler FOREIGN KEY(ruler_id) REFERENCES ruler (id), 
	CONSTRAINT fk_reign_period_id_period FOREIGN KEY(period_id) REFERENCES period (id), 
	CONSTRAINT fk_reign_dynasty_id_dynasty FOREIGN KEY(dynasty_id) REFERENCES dynasty (id), 
	CONSTRAINT fk_reign_city_id_city FOREIGN KEY(city_id) REFERENCES city (id)
);
CREATE TABLE ruler (
	name VARCHAR(100) NOT NULL, 
	id INTEGER NOT NULL, 
	CONSTRAINT pk_ruler PRIMARY KEY (id), 
	CONSTRAINT uq_ruler_name UNIQUE (name)
);
CREATE TABLE ruler_tablet (
	ruler_id INTEGER NOT NULL, 
	tablet_id INTEGER NOT NULL, 
	CONSTRAINT pk_ruler_tablet PRIMARY KEY (ruler_id, tablet_id), 
	CONSTRAINT fk_ruler_tablet_ruler_id_ruler FOREIGN KEY(ruler_id) REFERENCES ruler (id) ON DELETE CASCADE, 
	CONSTRAINT fk_ruler_tablet_tablet_id_tablet FOREIGN KEY(tablet_id) REFERENCES tablet (id) ON DELETE CASCADE
);
CREATE TABLE script_type (
	script VARCHAR(50) NOT NULL, 
	id INTEGER NOT NULL, 
	CONSTRAINT pk_script_type PRIMARY KEY (id), 
	CONSTRAINT uq_script_type_script UNIQUE (script)
);
CREATE TABLE sign (
	sign_ref VARCHAR(150) NOT NULL, 
	id INTEGER NOT NULL, 
	CONSTRAINT pk_sign PRIMARY KEY (id)
);
CREATE TABLE sign_list (
	name VARCHAR(50) NOT NULL, 
	position INTEGER NOT NULL, 
	id INTEGER NOT NULL, oracc_list VARCHAR(20), 
	CONSTRAINT pk_sign_list PRIMARY KEY (id), 
	CONSTRAINT uq_sign_list_name UNIQUE (name), 
	CONSTRAINT uq_sign_list_position UNIQUE (position)
);
CREATE TABLE sign_list_entry (
	cdp_id INTEGER NOT NULL, 
	sign_list_id INTEGER NOT NULL, 
	number VARCHAR(50) NOT NULL, 
	id INTEGER NOT NULL, 
	CONSTRAINT pk_sign_list_entry PRIMARY KEY (id), 
	CONSTRAINT fk_sign_list_entry_cdp_id_cdp FOREIGN KEY(cdp_id) REFERENCES cdp (id) ON DELETE CASCADE, 
	CONSTRAINT fk_sign_list_entry_sign_list_id_sign_list FOREIGN KEY(sign_list_id) REFERENCES sign_list (id), 
	CONSTRAINT uq_sign_list_entry_cdp_id UNIQUE (cdp_id, sign_list_id)
);
CREATE TABLE sign_name (
	cdp_id INTEGER NOT NULL, 
	source VARCHAR(20) NOT NULL, 
	name VARCHAR(150) NOT NULL, 
	id INTEGER NOT NULL, 
	CONSTRAINT pk_sign_name PRIMARY KEY (id), 
	CONSTRAINT ck_sign_name_source CHECK (source IN ('description', 'oracc', 'cdli')), 
	CONSTRAINT fk_sign_name_cdp_id_cdp FOREIGN KEY(cdp_id) REFERENCES cdp (id) ON DELETE CASCADE, 
	CONSTRAINT uq_sign_name_cdp_id UNIQUE (cdp_id, source)
);
CREATE TABLE sub_locality (
	name VARCHAR(100) NOT NULL, 
	locality_id INTEGER, 
	id INTEGER NOT NULL, 
	CONSTRAINT pk_sub_locality PRIMARY KEY (id), 
	CONSTRAINT fk_sub_locality_locality_id_locality FOREIGN KEY(locality_id) REFERENCES locality (id), 
	CONSTRAINT uq_sub_locality_name UNIQUE (name)
);
CREATE TABLE sub_period (
	name VARCHAR(100) NOT NULL, 
	period_id INTEGER NOT NULL, 
	id INTEGER NOT NULL, 
	CONSTRAINT pk_sub_period PRIMARY KEY (id), 
	CONSTRAINT fk_sub_period_period_id_period FOREIGN KEY(period_id) REFERENCES period (id), 
	CONSTRAINT uq_sub_period_name UNIQUE (name)
);
CREATE TABLE subperiod_dynasty (
	subperiod_id INTEGER NOT NULL, 
	dynasty_id INTEGER NOT NULL, 
	CONSTRAINT pk_subperiod_dynasty PRIMARY KEY (subperiod_id, dynasty_id), 
	CONSTRAINT fk_subperiod_dynasty_dynasty_id_dynasty FOREIGN KEY(dynasty_id) REFERENCES dynasty (id) ON DELETE CASCADE, 
	CONSTRAINT fk_subperiod_dynasty_subperiod_id_sub_period FOREIGN KEY(subperiod_id) REFERENCES sub_period (id) ON DELETE CASCADE
);
CREATE TABLE surface (
	name VARCHAR(50) NOT NULL, 
	id INTEGER NOT NULL, 
	CONSTRAINT pk_surface PRIMARY KEY (id), 
	CONSTRAINT uq_surface_name UNIQUE (name)
);
CREATE TABLE "tablet" (
	museum_number VARCHAR(75) NOT NULL, 
	medium_id INTEGER NOT NULL, 
	script_type_id INTEGER, 
	city_id INTEGER, 
	city_site_id INTEGER, 
	origin_city_id INTEGER, 
	publication VARCHAR(200), 
	period_id INTEGER NOT NULL, 
	sub_period_id INTEGER, 
	from_id INTEGER, 
	eponym_id INTEGER, 
	absolute_month VARCHAR(10), 
	absolute_day VARCHAR(10), 
	ancient_year VARCHAR(10), 
	ancient_month VARCHAR(10), 
	ancient_day VARCHAR(10), 
	text_vehicle_id INTEGER, 
	locality_id INTEGER, 
	sub_locality_id INTEGER, 
	notes VARCHAR(500), 
	method_id INTEGER, 
	genre_id INTEGER, 
	function_id INTEGER, 
	reign_id INTEGER, 
	author_id INTEGER, 
	id INTEGER NOT NULL, 
	year INTEGER, 
	CONSTRAINT pk_tablet PRIMARY KEY (id), 
	CONSTRAINT uq_tablet_museum_number UNIQUE (museum_number), 
	CONSTRAINT fk_tablet_script_type_id_script_type FOREIGN KEY(script_type_id) REFERENCES script_type (id), 
	CONSTRAINT fk_tablet_city_id_city FOREIGN KEY(city_id) REFERENCES city (id), 
	CONSTRAINT fk_tablet_text_vehicle_id_text_vehicle FOREIGN KEY(text_vehicle_id) REFERENCES text_vehicle (id), 
	CONSTRAINT fk_tablet_from_id_correspondent FOREIGN KEY(from_id) REFERENCES correspondent (id), 
	CONSTRAINT fk_tablet_origin_city_id_city FOREIGN KEY(origin_city_id) REFERENCES city (id), 
	CONSTRAINT fk_tablet_locality_id_locality FOREIGN KEY(locality_id) REFERENCES locality (id), 
	CONSTRAINT fk_tablet_period_id_period FOREIGN KEY(period_id) REFERENCES period (id), 
	CONSTRAINT fk_tablet_sub_period_id_sub_period FOREIGN KEY(sub_period_id) REFERENCES sub_period (id), 
	CONSTRAINT fk_tablet_reign_id_reign FOREIGN KEY(reign_id) REFERENCES reign (id), 
	CONSTRAINT fk_tablet_author_id_author FOREIGN KEY(author_id) REFERENCES author (id), 
	CONSTRAINT ck_tablet_city_or_locality CHECK (city_id IS NULL OR locality_id IS NULL), 
	CONSTRAINT fk_tablet_eponym_id_eponym FOREIGN KEY(eponym_id) REFERENCES eponym (id), 
	CONSTRAINT fk_tablet_genre_id_genre FOREIGN KEY(genre_id) REFERENCES genre (id), 
	CONSTRAINT fk_tablet_sub_locality_id_sub_locality FOREIGN KEY(sub_locality_id) REFERENCES sub_locality (id), 
	CONSTRAINT fk_tablet_medium_id_medium FOREIGN KEY(medium_id) REFERENCES medium (id), 
	CONSTRAINT fk_tablet_method_id_method FOREIGN KEY(method_id) REFERENCES method (id), 
	CONSTRAINT fk_tablet_function_id_function FOREIGN KEY(function_id) REFERENCES function (id), 
	CONSTRAINT fk_tablet_city_site_id_city_site FOREIGN KEY(city_site_id) REFERENCES city_site (id)
);
CREATE TABLE tablet_correspondent (
	tablet_id INTEGER NOT NULL, 
	correspondent_id INTEGER NOT NULL, 
	CONSTRAINT pk_tablet_correspondent PRIMARY KEY (tablet_id, correspondent_id), 
	CONSTRAINT fk_tablet_correspondent_correspondent_id_correspondent FOREIGN KEY(correspondent_id) REFERENCES correspondent (id) ON DELETE CASCADE, 
	CONSTRAINT fk_tablet_correspondent_tablet_id_tablet FOREIGN KEY(tablet_id) REFERENCES tablet (id) ON DELETE CASCADE
);
CREATE TABLE text_vehicle (
	name VARCHAR(100) NOT NULL, 
	bm_catalogue VARCHAR(100), 
	cdli VARCHAR(100), 
	id INTEGER NOT NULL, 
	CONSTRAINT pk_text_vehicle PRIMARY KEY (id), 
	CONSTRAINT uq_text_vehicle_name UNIQUE (name)
);
CREATE UNIQUE INDEX ix_sign_sign_ref ON sign (sign_ref);
CREATE INDEX ix_city_locality_id ON city (locality_id);
CREATE INDEX ix_city_site_city_id ON city_site (city_id);
CREATE INDEX ix_ruler_tablet_tablet_id ON ruler_tablet (tablet_id);
CREATE INDEX ix_sub_locality_locality_id ON sub_locality (locality_id);
CREATE INDEX ix_sub_period_period_id ON sub_period (period_id);
CREATE INDEX ix_subperiod_dynasty_dynasty_id ON subperiod_dynasty (dynasty_id);
CREATE INDEX ix_tablet_correspondent_correspondent_id ON tablet_correspondent (correspondent_id);
CREATE INDEX ix_correspondent_ruler_id ON correspondent (ruler_id);
CREATE INDEX ix_correspondent_non_ruler_id ON correspondent (non_ruler_id);
CREATE INDEX ix_sign_list_entry_cdp_id ON sign_list_entry (cdp_id);
CREATE INDEX ix_sign_list_entry_sign_list_id ON sign_list_entry (sign_list_id);
CREATE INDEX ix_sign_name_cdp_id ON sign_name (cdp_id);
CREATE INDEX ix_sign_name_name ON sign_name (name);
CREATE INDEX ix_cdp_sign_id ON cdp (sign_id);
CREATE INDEX ix_oracc_sign_name ON oracc_sign (name);
CREATE INDEX ix_oracc_list_number_list_name_number ON oracc_list_number (list_name, number);
CREATE INDEX ix_oracc_list_number_oracc_sign_id ON oracc_list_number (oracc_sign_id);
CREATE INDEX ix_change_set_reverts_id ON change_set (reverts_id);
CREATE INDEX ix_change_change_set_id ON change (change_set_id);
CREATE INDEX ix_change_table_name_record_id ON change (table_name, record_id);
CREATE TRIGGER change_set_no_update BEFORE UPDATE ON change_set BEGIN SELECT RAISE(ABORT, 'change_set rows cannot be changed or deleted'); END;
CREATE TRIGGER change_set_no_delete BEFORE DELETE ON change_set BEGIN SELECT RAISE(ABORT, 'change_set rows cannot be changed or deleted'); END;
CREATE TRIGGER change_no_update BEFORE UPDATE ON change BEGIN SELECT RAISE(ABORT, 'change rows cannot be changed or deleted'); END;
CREATE TRIGGER change_no_delete BEFORE DELETE ON change BEGIN SELECT RAISE(ABORT, 'change rows cannot be changed or deleted'); END;
CREATE INDEX ix_cdli_artifact_tablet_id ON cdli_artifact (tablet_id);
CREATE INDEX ix_oracc_text_tablet_id ON oracc_text (tablet_id);
CREATE INDEX ix_instance_sign_id ON instance (sign_id);
CREATE INDEX ix_instance_language_id ON instance (language_id);
CREATE INDEX ix_instance_surface_id ON instance (surface_id);
CREATE INDEX ix_instance_function_id ON instance (function_id);
CREATE INDEX ix_instance_tablet_id ON instance (tablet_id);
CREATE INDEX ix_eponym_year_eponym_id ON eponym_year (eponym_id);
CREATE INDEX ix_tablet_city_id ON tablet (city_id);
CREATE INDEX ix_tablet_from_id ON tablet (from_id);
CREATE INDEX ix_tablet_locality_id ON tablet (locality_id);
CREATE INDEX ix_tablet_origin_city_id ON tablet (origin_city_id);
CREATE INDEX ix_tablet_script_type_id ON tablet (script_type_id);
CREATE INDEX ix_tablet_text_vehicle_id ON tablet (text_vehicle_id);
CREATE INDEX ix_tablet_city_site_id ON tablet (city_site_id);
CREATE INDEX ix_tablet_function_id ON tablet (function_id);
CREATE INDEX ix_tablet_medium_id ON tablet (medium_id);
CREATE INDEX ix_tablet_period_id ON tablet (period_id);
CREATE INDEX ix_tablet_sub_locality_id ON tablet (sub_locality_id);
CREATE INDEX ix_tablet_author_id ON tablet (author_id);
CREATE INDEX ix_tablet_eponym_id ON tablet (eponym_id);
CREATE INDEX ix_tablet_genre_id ON tablet (genre_id);
CREATE INDEX ix_tablet_method_id ON tablet (method_id);
CREATE INDEX ix_tablet_reign_id ON tablet (reign_id);
CREATE INDEX ix_tablet_sub_period_id ON tablet (sub_period_id);
CREATE INDEX ix_reign_dynasty_id ON reign (dynasty_id);
CREATE INDEX ix_reign_ruler_id ON reign (ruler_id);
CREATE INDEX ix_reign_city_id ON reign (city_id);
CREATE INDEX ix_reign_period_id ON reign (period_id);
CREATE INDEX ix_reign_sub_period_id ON reign (sub_period_id);
CREATE TRIGGER tablet_sub_period_insert BEFORE INSERT ON tablet FOR EACH ROW WHEN NEW.sub_period_id IS NOT NULL AND NEW.period_id IS NOT (SELECT period_id FROM sub_period WHERE id = NEW.sub_period_id) BEGIN SELECT RAISE(ABORT, 'tablet_sub_period: The sub-period of a tablet must belong to the period of the tablet.'); END;
CREATE TRIGGER tablet_sub_period_update BEFORE UPDATE OF period_id, sub_period_id ON tablet FOR EACH ROW WHEN NEW.sub_period_id IS NOT NULL AND NEW.period_id IS NOT (SELECT period_id FROM sub_period WHERE id = NEW.sub_period_id) BEGIN SELECT RAISE(ABORT, 'tablet_sub_period: The sub-period of a tablet must belong to the period of the tablet.'); END;
CREATE TRIGGER reign_sub_period_insert BEFORE INSERT ON reign FOR EACH ROW WHEN NEW.sub_period_id IS NOT NULL AND NEW.period_id IS NOT (SELECT period_id FROM sub_period WHERE id = NEW.sub_period_id) BEGIN SELECT RAISE(ABORT, 'reign_sub_period: The sub-period of a reign must belong to the period of the reign.'); END;
CREATE TRIGGER reign_sub_period_update BEFORE UPDATE OF period_id, sub_period_id ON reign FOR EACH ROW WHEN NEW.sub_period_id IS NOT NULL AND NEW.period_id IS NOT (SELECT period_id FROM sub_period WHERE id = NEW.sub_period_id) BEGIN SELECT RAISE(ABORT, 'reign_sub_period: The sub-period of a reign must belong to the period of the reign.'); END;
CREATE TRIGGER tablet_year_eponym_insert BEFORE INSERT ON tablet FOR EACH ROW WHEN NEW.eponym_id IS NOT NULL AND EXISTS (SELECT 1 FROM eponym_year WHERE year = NEW.year AND eponym_id IS NOT NEW.eponym_id) BEGIN SELECT RAISE(ABORT, 'tablet_year_eponym: A tablet must have the eponym of its year.'); END;
CREATE TRIGGER tablet_year_eponym_update BEFORE UPDATE OF year, eponym_id ON tablet FOR EACH ROW WHEN NEW.eponym_id IS NOT NULL AND EXISTS (SELECT 1 FROM eponym_year WHERE year = NEW.year AND eponym_id IS NOT NEW.eponym_id) BEGIN SELECT RAISE(ABORT, 'tablet_year_eponym: A tablet must have the eponym of its year.'); END;
CREATE TRIGGER sub_period_period_update BEFORE UPDATE OF period_id ON sub_period FOR EACH ROW WHEN EXISTS (SELECT 1 FROM tablet WHERE sub_period_id = NEW.id AND period_id IS NOT NEW.period_id) OR EXISTS (SELECT 1 FROM reign WHERE sub_period_id = NEW.id AND period_id IS NOT NEW.period_id) BEGIN SELECT RAISE(ABORT, 'sub_period_period: A sub-period must have the period of its tablets and reigns.'); END;
CREATE TRIGGER year_eponym_insert BEFORE INSERT ON eponym_year FOR EACH ROW WHEN EXISTS (SELECT 1 FROM tablet WHERE year = NEW.year AND eponym_id IS NOT NULL AND eponym_id IS NOT NEW.eponym_id) BEGIN SELECT RAISE(ABORT, 'year_eponym: A year must have the eponym of its tablets.'); END;
CREATE TRIGGER year_eponym_update BEFORE UPDATE OF year, eponym_id ON eponym_year FOR EACH ROW WHEN EXISTS (SELECT 1 FROM tablet WHERE year = NEW.year AND eponym_id IS NOT NULL AND eponym_id IS NOT NEW.eponym_id) BEGIN SELECT RAISE(ABORT, 'year_eponym: A year must have the eponym of its tablets.'); END;
COMMIT;
